def parse_id(sid):
    res = []
    for p in sid.split('-'):
        try: res.append(int(p))
        except: res.append(p)
    return tuple(res)

selected_obs = {}
for obs in observations:
    if obs['observed_at'] > cutoff or obs['result'] != 'captured':
        continue
    key = (obs['consumer'], obs['ring'], obs['package'], obs['fault_point'])
    if key not in selected_obs:
        selected_obs[key] = obs
    else:
        prev = selected_obs[key]
        if obs['observed_at'] > prev['observed_at'] or (obs['observed_at'] == prev['observed_at'] and parse_id(obs['id']) > parse_id(prev['id'])):
            selected_obs[key] = obs

def get_decision(state, c_obj):
    wp = state.get('write_phase')
    if wp == 'not_started': return 'retry_same_image'
    if wp == 'complete_uncommitted' and state.get('journal_integrity') == 'valid' and state.get('new_image_integrity') == 'verified' and state.get('resume_token') == 'valid': return 'resume_commit'
    if state.get('rollback_snapshot') == 'verified': return 'rollback_then_retry'
    if state.get('image_cache') == 'verified' and c_obj.get('rollout', {}).get('reimage_allowed'): return 'reimage_then_retry'
    return 'unrecoverable'

gates = {}
for c in estate['consumers']:
    c_id = c['id']
    if c['version'] not in packages:
        continue
    pkg = packages[c['version']]
    pkg_id = pkg['id']
    for ring in c.get('rollout', {}).get('rings', []):
        gate_key = (c_id, ring, pkg_id)
        base_context = f"{c_id}\x00{ring}\x00{pkg_id}\x00{pkg['to']}\x00{pkg['image_digest']}".encode('utf-8')
        base_key = hashlib.sha256(bytes.fromhex(upgrade_states[c_id]) + base_context).digest()
        if ring == 'canary':
            parent_bytes = hashlib.sha256(b"captured-v2\x00" + bytes.fromhex(upgrade_states[c_id])).digest()
        else:
            parent_bytes = bytes.fromhex(gates[(c_id, 'canary', pkg_id)]['final_receipt'])
        steps = []
        for fp in fixtures['fault_points']:
            obs_key = (c_id, ring, pkg_id, fp)
            if obs_key in selected_obs:
                obs = selected_obs[obs_key]
                state_digest = obs['state_digest']
                decision = get_decision(obs['state'], c)
                wu = work_units[decision]
                message = b"recover-v2\x00" + parent_bytes + b"\x00" + fp.encode('utf-8') + b"\x00" + obs['id'].encode('utf-8') + b"\x00" + bytes.fromhex(state_digest) + b"\x00" + decision.encode('utf-8') + b"\x00" + str(wu).encode('utf-8')
                receipt = hmac_sha256(base_key, message)
                steps.append({'fault_point': fp, 'evidence': obs['id'], 'decision': decision, 'work_units': wu, 'receipt': receipt})
                parent_bytes = bytes.fromhex(receipt)
        gates[gate_key] = {'steps': steps, 'final_receipt': parent_bytes.hex()}

